   using(var owned=new OwnedClientFixture(f.E.Game)){var running=new Engine(f.E.Game,f.E.User,f.E.Data,false,()=>new SteamLaunchOptionsSnapshot(null,0,null,SteamLaunchOptionsState.UnknownIdentity),name=>name=="ProjectZomboid64"?new[]{Process.GetProcessById(owned.Process.Id)}:new Process[0]);Assert(Refused(running.GuardLaunch),"verified selected-install client still blocks launch despite unknown Steam identity");}
