  static void FinalEvidence(){
   foreach(string change in new[]{"selected","inactive-id","membership","version","source-record","default","retention"}){
    var f=new Fixture(true);f.Mod("Child");f.Mod("Other");f.Mods("Child");
    byte[] addonBytes=null;string addonJar=null;
    if(change=="retention"){f.Java();string addon=Addon(f,"surface");addonJar=Path.Combine(addon,"42/media/java/client/Addon.jar");addonBytes=File.ReadAllBytes(addonJar);File.Delete(addonJar);f.Mods("ZombieBuddy","Viewpoint","ViewpointSurface");}
    var report=LaunchPreflight.CheckLaunch(f.E,false,false,change=="retention"?"server":"normal",null,true);
    Assert(report.canLaunch,"evidence fixture begins valid: "+change);report.Evidence.Validate();
    if(change=="retention")File.WriteAllBytes(addonJar,addonBytes);
    else if(change=="membership")f.Mod("NewDuplicate","id=Child\n");
    else if(change=="source-record"){Directory.CreateDirectory(f.E.Data);File.WriteAllText(Path.Combine(f.E.Data,"workshop-paths.json"),"{}");}
    else{
     string path=change=="selected"?Path.Combine(f.E.User,"mods","Child","42","mod.info"):change=="inactive-id"?Path.Combine(f.E.User,"mods","Other","42","mod.info"):change=="version"?Path.Combine(f.E.Game,"game-version.txt"):f.E.Mods;
     string original=File.ReadAllText(path);DateTime stamp=File.GetLastWriteTimeUtc(path);
     File.WriteAllText(path,change=="selected"?"id=Other\n":change=="inactive-id"?"id=Child\n":change=="version"?"42.1":original.Replace("Child","Other"));File.SetLastWriteTimeUtc(path,stamp);
    }
    string failure="";try{LaunchProfiles.Stage(f.E,new ProfileLaunchRequest{Kind="normal",ValidateBeforeStage=report.Evidence.Validate});}catch(Exception ex){failure=ex.Message;}
    Assert(failure.Contains("改变")&&!LaunchProfiles.Pending(f.E)&&!Directory.Exists(Path.Combine(f.E.User,"mods","OrangeLauncherSession")),"fresh evidence rejects "+change+" before staging writes");
   }
  }
