  static void StrictSaveSelection(){
   var f=new Fixture(true);string save=Path.Combine(f.E.User,"Saves","Sandbox","Missing");Directory.CreateDirectory(save);
   File.WriteAllBytes(Path.Combine(save,"mods.txt"),SaveProfiles.ReplaceDefaultMods(null,new[]{"AbsentSelectedSaveMod"}));
