   Assert(!report.canLaunch&&report.items.Single(i=>i.id=="mods").details.Any(d=>d.Contains("AbsentSelectedSaveMod")),"focused native save preflight retains strict missing-ID refusal and details");
   Assert(files.SequenceEqual(f.Files()),"strict selected-save check is read-only");
   using(var controller=new ModernController(f.E.Game,f.E.User,f.E.Data,false)){
    LaunchPreflightBlockedException blocked=null;try{controller.Execute("profileLaunch",GameStartupPresentationTests.Begin(controller,"save","Sandbox/Missing"));}catch(LaunchPreflightBlockedException ex){blocked=ex;}
    Assert(blocked!=null&&Json.Serialize(blocked.Report).Contains("AbsentSelectedSaveMod")&&!Directory.Exists(Path.Combine(f.E.Game,"OrangeLauncherRuntime"))&&!LaunchProfiles.Pending(f.E),"direct native missing-save refusal precedes Prepare and Stage");
   }
